    "gemm_tiles": _op_gemm_tiles,
    "gemm_prefetch": _op_gemm_prefetch,
    "scores_residency": _op_scores_residency,
    "fuse_bias_gelu": _op_fuse_bias_gelu,
    "hw_set": _op_hw_set,
    "workgroups": _op_workgroups,
