    if MAX_M // max(m_t, 1) > 32:
        errs.append(f"m_tile={m_t}: >32 m-iterations, instruction explosion")
    if recipe["attention"]["scores"] not in SCORES_SPACES:
        errs.append("bad scores space")
    return errs


