        h = Hardware.from_dict(hw)
        h.validate()
    except Exception as e:
        return [f"hardware invalid: {e}"]
    area = h.area_mm2()
    if area > AREA_LIMIT_MM2:
        errs.append(f"area {area:.2f}mm2 > {AREA_LIMIT_MM2}")
    return errs


