    """Flat diff of two recipes: {dotted.path: [old, new]}."""
    out = {}

    def walk(x, y, p):
        if isinstance(x, dict) and isinstance(y, dict):
            for k in sorted(set(x) | set(y)):
                walk(x.get(k), y.get(k), f"{p}{k}.")
        elif x != y:
            out[p[:-1]] = [x, y]

    walk(a, b, "")
    return out

